var rules = []Rule{
	{ID: "resources.references-unreadable", Statement: bilingual("The definitions cannot be updated; nothing was saved:\n%s", "次の{{team-definition}}を書き換えられないため、保存しませんでした:\n%s"), ErrorKey: "error.resource_references_unreadable", Slots: []TermID{TermTeamDefinition}},
	{ID: "resources.references-write", Statement: bilingual("Writing failed. Completed:\n%s\nNot completed:\n%s\n%s", "書き込みに失敗しました。済んだもの:\n%s\n済んでいないもの:\n%s\n%s"), ErrorKey: "error.resource_references_write", Slots: []TermID{TermTeamDefinition, TermTeamDefinition, TermReason}},
	{ID: "refresh.no-pane", Statement: bilingual("%s has no pane; {{refresh}} does not add a {{member}} to a running {{team}}.", "%s のペインが無い。refresh で動いている{{team}}に{{member}}を追加することはできない。"), Recovery: bilingual("Use hergy apply to add it.", "追加するには hergy apply を使う。"), ErrorKey: "refresh.use_apply", Slots: []TermID{"member"}},
	{ID: "refresh.own-pane", Statement: bilingual("%s runs in your own pane; a {{member}} cannot {{refresh}} itself. Run it from another pane, or as the {{human}}", "%s はこのペインで動いています。自分自身は{{start}}し直せないので、別のペインから実行するか、{{human}}が実行してください"), ErrorKey: "error.refresh_self", Slots: []TermID{"member"}},
	{ID: "refresh.busy-pane", Statement: bilingual("%s: the pane named after it is running something else (pane %s); run `hergy down` then `hergy up`", "%s のペイン（%s）では別のものが動いています。hergy down のあと hergy up し直してください"), ErrorKey: "error.refresh_pane_busy", Slots: []TermID{"member", "place"}},
	{ID: "refresh.state", Statement: bilingual("%s: {{status}}=%q; wait until the {{agent}} is {{idle}} or done", "%s はいま %q です。idle か done になってから実行してください"), ErrorKey: "error.reset_before_refresh", Slots: []TermID{"member", "status"}},
	{ID: "apply.env-changed", Statement: bilingual("%s's environment changed, so hergy cannot {{apply}} it. [[env.fixed]]", "%s の環境変数が変わり、{{apply}}できない。[[env.fixed]]"), ErrorKey: "apply.refused_env", Slots: []TermID{"member"}},
	{ID: "apply.state", Statement: bilingual("%s is {{working}} or {{waiting-for-permission}}, so hergy cannot {{apply}} it now", "%s は{{working}}か{{waiting-for-permission}}なので、今は{{apply}}できません"), ErrorKey: "apply.refused_state", Slots: []TermID{"member"}},
	{ID: "apply.removed", Statement: bilingual("%s is no longer in the {{team-definition}}. Stop the {{team}} and {{start}} it again to {{apply}} this (hergy down, then hergy up)", "%s は{{team-definition}}にありません。{{apply}}するには、{{team}}を終了して{{refresh}}てください（hergy down、hergy up）"), ErrorKey: "apply.refused_removed", Slots: []TermID{"member"}},
	{ID: "up.name-taken", Statement: bilingual("a {{team}} named %s is already running; {{start}} it under another name", "%s という名前の{{team}}がすでに動いています。別の名前で{{start}}してください"), ErrorKey: "error.team_name_taken", Slots: []TermID{"team-name"}},
	{ID: "hire.purpose-outside", Statement: bilingual("%[1]s cannot hire for \"%[2]s\"; it may hire for: %[3]s (team.yaml workers:). Pass one of those {{purpose}}s", "%[1]s は{{purpose}}「%[2]s」で{{worker}}を呼べません。呼べる{{purpose}}: %[3]s（team.yaml の workers:）。この中の{{purpose}}を指定してください"), ErrorKey: "error.hire_purpose_outside", Slots: []TermID{"member", "purpose", "purpose"}},
	{ID: "hire.purpose-nobody", Statement: bilingual("no {{member}} may hire a {{worker}} for \"%s\"; who may hire for what: %s. Pass one of those {{purpose}}s", "{{purpose}}「%s」で{{worker}}を呼べる{{member}}はいません。呼べる{{purpose}}: %s。この中の{{purpose}}を指定してください"), ErrorKey: "error.hire_purpose_nobody", Slots: []TermID{"purpose", "member"}},
	{ID: "hire.from-many", Statement: bilingual("--from is required ({{member}}s hiring for this {{purpose}}: %s)", "--from を指定してください（この{{purpose}}の{{worker}}を持つ{{member}}: %s）"), ErrorKey: "error.from_required_many", Slots: []TermID{"member"}},
	{ID: "flag.as.up", Statement: bilingual("{{start|cap}} the {{team}} under this {{team-name}} (default: the {{team-definition-name}})", "この{{team-name}}で{{start}}する（既定は{{team-definition-name}}）")},
	{ID: "flag.dry.up", Statement: bilingual("Print the plan (each {{member}}'s {{prompt}} as text) and {{start}} nothing", "{{start}}せず、計画（{{member}}ごとの{{prompt}}）だけを表示する")},
	{ID: "flag.dry.down", Statement: bilingual("Print what would close and close nothing", "閉じる予定だけを表示し、何も閉じない")},
	{ID: "flag.json.status", Statement: bilingual("Print the rows as JSON (state and unchanged_minutes) instead of text", "行を JSON で表示する（state と unchanged_minutes）")},
	{ID: "flag.all.refresh", Statement: bilingual("Restart every {{member}} (not with a {{member}})", "全{{member}}を{{start}}し直す（{{member}}とは同時に指定できない）")},
	{ID: "flag.dry.refresh", Statement: bilingual("Print what would restart or be added, and change nothing", "{{start}}し直す予定と、足す予定を表示し、何も変えない")},
	{ID: "flag.all.reprompt", Statement: bilingual("Send it to every {{member}} (not with a {{member}})", "全{{member}}に送り直す（{{member}}とは同時に指定できない）")},
	{ID: "flag.dry.reprompt", Statement: bilingual("Print what would be sent and send nothing", "送る予定だけを表示し、何も送らない")},
	{ID: "flag.dry.apply", Statement: bilingual("Print each {{member}}'s way of applying, what changed and the {{team}}'s {{rule-note}}s", "{{member}}ごとの{{apply}}の仕方・変わったこと・{{team}}の知らせを表示する")},
	{ID: "flag.dry.nudge", Statement: bilingual("Print what would be sent and send nothing", "送る予定だけを表示し、何も送らない")},
	{ID: "flag.dry.stop", Statement: bilingual("Print what would {{stop}} and change nothing", "{{stop}}予定だけを表示し、何も変えない")},
	{ID: "flag.from.tell", Statement: bilingual("The {{member}} or {{worker}} the message is from (short name or {{herdr-name}})", "誰からの本文か（{{member}}か{{worker}}の短い名前か {{herdr-name}}）")},
	{ID: "flag.dry.tell", Statement: bilingual("Print what would be sent and send nothing", "送る予定だけを表示し、何も送らない")},
	{ID: "flag.purpose.hire", Statement: bilingual("What the {{worker}} is for (required)", "{{worker}}の{{purpose}}（必須）")},
	{ID: "flag.task.hire", Statement: bilingual("The task text handed to the {{worker}} (required)", "{{worker}}に渡す依頼の文（必須）")},
	{ID: "flag.from.hire", Statement: bilingual("The {{member}} that hires the {{worker}} (short {{member-name}} or {{herdr-name}})", "{{worker}}を追加する{{member}}（短い{{member-name}}か {{herdr-name}}）")},
	{ID: "flag.dry.hire", Statement: bilingual("Print the plan and {{start}} nothing", "{{start}}せず、計画だけを表示する")},
	{ID: "flag.log.turns", Statement: bilingual("Print the watcher's log (each line with its time) and {{stop}}", "見張りのログ（1 行ごとに時刻付き）を表示して終わる")},
	{ID: "flag.definition.turns", Statement: bilingual("The {{team-definition}} the {{team}} runs from (hergy up passes it)", "{{team}}が動いている{{team-definition}}（hergy up が渡す）")},
	{ID: "flag.dry.migrate", Statement: bilingual("Inspect every conversion without writing", "全対象を検査して表示する。書き込まない")},
	{ID: "flag.global.migrate", Statement: bilingual("Convert {{global}} settings instead of the {{project}}", "{{project}}ではなく{{global}}を変換する")},
	{ID: "flag.port.serve", Statement: bilingual("The port to listen on (default 8787; 0 lets the operating system pick a free one)", "待ち受けるポート（既定は 8787。0 は空きポートを OS が選ぶ）")},
	{ID: "flag.no-open.serve", Statement: bilingual("Print the URL and open no browser", "URL を出すだけで、ブラウザを開かない")},
	{ID: "flag.ai.cheat", Statement: bilingual("Print it for an {{agent}} (always English)", "AI 向け（英語）で表示する")},
	{ID: "flag.lang", Statement: bilingual("Language of the command line's output (default en)", "コマンドの出力の言語（既定は en）")},
	{ID: "flag.help", Statement: bilingual("Show this text", "この{{description}}を表示する")},
	{ID: "flag.dir", Statement: bilingual("The {{project}} root to resolve against", "{{project}}の場所を指定する")},
	{ID: "flag.json", Statement: bilingual("With --dry, print the plan as JSON (--dry is required)", "--dry の計画を JSON で表示する（--dry が必要）")},
	{ID: "startup.timeout", Statement: bilingual("Startup timeout in milliseconds, 3001..300000 (default 30000)", "{{start}}を待つ時間（ミリ秒。3001〜300000、既定 30000）")},
	{ID: "team.selection", Statement: bilingual("The {{team}} to act on, by {{team-name}}.", "対象の{{team-name}}。")},
	{ID: "hire.team-selection", Statement: bilingual("The {{team}}, by {{team-name}} or {{team-definition-name}}.", "対象の{{team}}（{{team-name}}か{{team-definition-name}}）。")},
	{ID: "env.fixed", Statement: bilingual("env is fixed when a pane is made. After editing env, run hergy down then hergy up.", "env はペインの作成時に決まる。変更したら hergy down のあと hergy up を使う。")},
	{ID: "prompt.missing-receipt", Statement: bilingual("not received: %s (pane %s): %s\nretry: %s", "届いていません: %s（ペイン %s）: %s\n送り直す: %s"), ErrorKey: "launcher.undelivered", Slots: []TermID{"member", "place", "reason", "reprompt"}},
	{ID: "control.nudge-state", Statement: bilingual("%s: {{status}} %q; a nudge is sent only when the {{agent}} is {{idle}} or done. Run it again then", "%s はいま %q です。idle か done のときだけ送れます。idle か done になってから、もう一度実行してください"), ErrorKey: "error.nudge_busy", Slots: []TermID{"member", "status"}},
	{ID: "control.stop-self", Statement: bilingual("%s runs in your own pane; a {{member}} cannot {{stop}} itself. Run it from another pane, or as the {{human}}", "%s はこのペインで動いています。自分自身は止められないので、別のペインから実行するか、{{human}}が実行してください"), ErrorKey: "error.stop_self", Slots: []TermID{"member"}},
	{ID: "refresh.no-team-pane", Statement: bilingual("%s: the {{team}} tab is absent or has no pane to split; run `hergy down` then `hergy up`", "%s を追加できる{{team}}のペインが見つかりません。hergy down のあと hergy up し直してください"), ErrorKey: "error.refresh_no_pane", Slots: []TermID{"member"}},
	{ID: "start.cwd-directory", Statement: bilingual("cwd is not a directory: %s; pass a directory to -C", "cwd がディレクトリではありません: %s。-C にディレクトリを指定してください"), ErrorKey: "error.cwd_not_dir", Slots: []TermID{"place"}},
	{ID: "start.live-names", Statement: bilingual("live {{agent}} names already in use: %s; run `hergy down`, then run this again", "その名前の{{agent}}がすでに動いています: %s。hergy down で{{team}}を終了してから、もう一度実行してください"), ErrorKey: "error.live_names_in_use", Slots: []TermID{"herdr-name"}},
	{ID: "runtime.managed-pane", Statement: bilingual("run inside a Herdr-managed shell pane (HERDR_ENV=1 and HERDR_PANE_ID are required)", "herdr のペインの中で実行してください（HERDR_ENV=1 と HERDR_PANE_ID が必要です）"), ErrorKey: "error.not_under_herdr"},
}
